/* Render precomputed seeded simulations. All numbers are generated by build.py. */
(() => {
  'use strict';
  const D=JSON.parse(document.getElementById('dataset').textContent);
  const el=id=>document.getElementById(id);
  const integer=x=>x.toLocaleString('en-US');
  const fmt=x=>x.toFixed(2);
  let active='boot',revision=0;
  const blue='#155ab6',orange='#b67524',dark='#253646';
  const stat=(value,label,extra='')=>`<div class="stat"><b class="${extra}">${value}</b><span>${label}</span></div>`;
  function baseLayout(narrow) {
    return {margin:{l:narrow?54:67,r:20,t:22,b:narrow?76:62},font:{family:'system-ui, sans-serif',size:12,color:dark},
      paper_bgcolor:'white',plot_bgcolor:'white',hovermode:'closest',datarevision:++revision,
      xaxis:{gridcolor:'#e5ebf1',zeroline:false,showline:true,linecolor:'#aebcca',nticks:narrow?4:7},
      yaxis:{gridcolor:'#e5ebf1',zeroline:false,showline:true,linecolor:'#aebcca'},
      legend:{orientation:'h',x:0,y:1.1,font:{size:11}}};
  }
  function vertical(x,color,dash='dash') {return {type:'line',xref:'x',yref:'paper',x0:x,x1:x,y0:0,y1:1,line:{color,width:1.5,dash}};}
  function render() {
    const n=el('sample-size').value,level=el('confidence').value,claim=el('null-mean').value;
    const s=D.scenarios[n],confidence=+level/100,alpha=1-confidence;
    const layout=baseLayout(document.documentElement.clientWidth<600);
    if(active==='coverage'){layout.margin.t=50;layout.legend.y=1.03;layout.legend.yanchor='bottom';}
    let traces=[];
    el('null-control').hidden=active!=='test';
    el('lab-panel').setAttribute('aria-labelledby','tab-'+active);
    document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===active)));
    if(active==='boot') {
      const h=s.bootstrap_hist,[lo,hi]=s.bootstrap_ci[level];
      el('panel-title').textContent='1. One sample → 5,000 bootstrap means';
      el('summary').innerHTML=stat(fmt(s.sample_mean)+' min','Observed sample mean')+stat('['+fmt(lo)+', '+fmt(hi)+']',level+'% percentile interval')+stat(integer(D.config.display_bootstrap_resamples),'Resamples from this same sample');
      traces=[{type:'bar',x:h.x,y:h.density,width:h.width,marker:{color:blue,line:{color:'white',width:.35}},customdata:h.count,
        hovertemplate:'Bootstrap mean: %{x:.3f} min<br>Density: %{y:.3f}<br>%{customdata:,} bootstrap means in bin<extra></extra>',showlegend:false}];
      layout.xaxis.title={text:'Bootstrap sample mean (minutes)',standoff:12};layout.yaxis.title={text:'Density (per minute)',standoff:8};layout.yaxis.rangemode='tozero';
      layout.shapes=[{type:'rect',xref:'x',yref:'paper',x0:lo,x1:hi,y0:0,y1:1,fillcolor:'#f8ecd9',line:{width:0},layer:'below'},vertical(lo,orange,'solid'),vertical(hi,orange,'solid'),vertical(D.config.population_mean,dark)];
      el('explanation').innerHTML=`Each resample draws <b>${n} observations with replacement</b> from the same observed sample. The ${level==='95'?'2.5th and 97.5th':'5th and 95th'} percentiles give the orange interval boundaries. The dashed black line marks the known simulated mean, 30 minutes. This is a distribution of resampled <b>means</b>, not of individual waiting times.`;
    } else if(active==='coverage') {
      const c=s.coverage[level];
      el('panel-title').textContent='2. Does this interval method cover the truth in new samples?';
      el('summary').innerHTML=stat(integer(c.covered)+' / '+integer(c.repetitions),'Intervals covering 30 minutes')+stat((100*c.rate).toFixed(2)+'%','Empirical coverage; target '+level+'%')+stat((100*c.mcse).toFixed(2)+' pp','Monte Carlo standard error');
      traces=[1,0].map(hit=>{
        const xs=[],ys=[],custom=[];
        for(const r of c.first_intervals.filter(r=>r.covered===hit)) {xs.push(r.low,r.high,null);ys.push(r.trial,r.trial,null);custom.push([r.trial,r.low,r.high],[r.trial,r.low,r.high],null);}
        return {type:'scatter',mode:'lines+markers',x:xs,y:ys,customdata:custom,name:hit?'Covers 30':'Misses 30',
          line:{color:hit?blue:orange,width:1.6},marker:{color:hit?blue:orange,size:4,symbol:hit?'circle':'diamond'},
          hovertemplate:'New sample %{customdata[0]}<br>Interval: [%{customdata[1]:.3f}, %{customdata[2]:.3f}] min<extra>%{fullData.name}</extra>'};
      });
      layout.xaxis.title={text:'Bootstrap interval endpoints (minutes)',standoff:12};layout.yaxis.title={text:'New sample number',standoff:8};layout.yaxis.range=[D.config.display_intervals+1,0];layout.yaxis.tickvals=[1,20,40,60];layout.shapes=[vertical(30,dark)];
      el('explanation').innerHTML=`The graph shows the <b>first ${D.config.display_intervals} intervals</b> in generation order; the summary uses <b>all ${integer(c.repetitions)}</b>. Each new population sample gets its own ${integer(D.config.coverage_bootstrap_resamples)} bootstrap resamples. Mean interval width is ${fmt(c.mean_width)} minutes. Coverage is a repeated-sampling property, not a ${level}% probability assigned to the fixed truth after observing an interval.`;
    } else {
      const t=s.tests[claim],test=t.by_level[level],h=test.hist;
      el('panel-title').textContent='3. Simulate a two-sided t-test under H₀: mean = '+claim+' minutes';
      el('summary').innerHTML=stat(t.t_observed.toFixed(3),'Observed t statistic')+stat(t.p.toPrecision(3),'Simulated two-sided p-value')+stat(test.reject?'Reject H₀':'Do not reject H₀','At α = '+alpha.toFixed(2),'decision');
      traces=[{type:'bar',x:h.x,y:h.density,width:h.width,customdata:h.count,showlegend:false,
        marker:{color:test.tail.map(v=>v?blue:'#bdc9d6'),line:{color:'white',width:.35}},
        hovertemplate:'Null t statistic: %{x:.3f}<br>Density: %{y:.3f}<br>%{customdata:,} simulated t statistics in bin<extra></extra>'}];
      layout.xaxis.title={text:'Studentized t statistic',standoff:12};layout.xaxis.range=[-test.bound,test.bound];layout.yaxis.title={text:'Null probability density',standoff:8};layout.yaxis.rangemode='tozero';
      layout.shapes=[{type:'rect',xref:'x',yref:'paper',x0:-test.bound,x1:-test.critical,y0:0,y1:1,fillcolor:'#f8ecd9',line:{width:0},layer:'below'},{type:'rect',xref:'x',yref:'paper',x0:test.critical,x1:test.bound,y0:0,y1:1,fillcolor:'#f8ecd9',line:{width:0},layer:'below'},vertical(-test.critical,orange),vertical(test.critical,orange),vertical(t.t_observed,dark,'solid')];
      el('explanation').innerHTML=`<b>Orange shaded regions</b> reject at α=${alpha.toFixed(2)}: |t| &gt; ${test.critical.toFixed(3)}. <b>Blue bars</b> are the simulated results at least as extreme as |observed t|. The p-value is (${integer(t.extreme)}+1)/(${integer(D.config.null_repetitions)}+1), not the probability H₀ is true. The solid black line is observed t. Standardizing makes the null curve translation-invariant, so changing the claimed mean moves observed t, not the underlying null shape. A non-rejection does not establish that the claim is true.`;
    }
    Plotly.react(el('chart'),traces,layout,{responsive:true,displaylogo:false,scrollZoom:false,displayModeBar:true,modeBarButtonsToRemove:['lasso2d','select2d','toImage']});
  }
  for(const id of ['sample-size','confidence','null-mean']) el(id).addEventListener('change',render);
  document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.panel;render();}));
  el('reset').addEventListener('click',()=>{el('sample-size').value='200';el('confidence').value='95';el('null-mean').value='30';active='boot';render();});
  let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,120);});
  if(typeof Plotly==='undefined')el('explanation').textContent='The local Plotly library did not load. Download the saved CSV results below.';
  else render();
  if(window.parent!==window)new ResizeObserver(()=>window.parent.postMessage({type:'blog8-height',height:document.body.scrollHeight+24},window.location.origin)).observe(document.body);
})();
